arguments.command:
cat results/ppo_countdown/metrics.jsonl | python3 -c "
import json, sys
for line in sys.stdin:
    d = json.loads(line)
    step = d['step']
    data = d['data']
    # Print the key metrics
    out = {'step': step}
    for k,v in data.items():
        if 'eval' in k or 'train' in k or 'rollout' in k or 'loss' in k or 'reward' in k or 'kl' in k or 'critic' in k or 'actor' in k or 'entropy' in k or 'clip' in k or 'ratio' in k or 'no_grad' in k:
            if isinstance(v, float):
                out[k] = round(v, 4)
    print(json.dumps(out))
"

